INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (1,1,'Locked blocks','L1: the research copy of §713.015 ended with "WHENEVER A SPECIFIC PROBLEM ARISES"; the 2026 official text does not. Please confirm the current wording, and whether a notice built on the old wording (if any is in use) needs replacing.');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (2,1,'Locked blocks','L1: is a separate page with its own e-signature and date enough to satisfy "signed by the owner and dated" when the whole contract is signed electronically?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (3,1,'Locked blocks','L1: the notice advises the owner to stipulate that lien releases come before any payment. Should the library offer a per-payment release clause (conditional progress releases under §713.20) as a C12 option?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (4,1,'Locked blocks','L2: which board address and phone does "as established by board rule" currently point to? Official pages show ZIP+4 codes 32399-1039, 32399-2215 and 32399-0791, and phones (850) 921-6593 (Fund) and 850-487-1395 (Board). Which rule establishes it?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (5,1,'Locked blocks','L4: correct wording when the business holds a local certificate of competency rather than a state registration or certification; and whether the qualifying agent''s name should appear.');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (6,1,'Locked blocks','L5: when should the builder insert the Florida §501.031 statement in addition to the FTC forms? Florida excludes sales that result "from a request for specific goods or services by the purchaser"; the FTC rule covers sales following the buyer''s invitation. Is inserting both whenever the sale was made at the home acceptable, or does including a Florida notice when Florida''s Act does not apply create any problem?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (7,1,'Locked blocks','L5: may the goods-return and trade-in paragraphs of the FTC NOTICE OF CANCELLATION be omitted as not "applicable" for a services contract, or must the form be printed whole?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (8,1,'Locked blocks','L5: the FTC rule requires the contract and forms in the language principally used in the oral sales presentation. The business owners are Brazilian and some sales will be presented in Portuguese. What must the builder do when the presentation was in Portuguese and the contract is English (the C19-B courtesy translation is locked pending your answer)?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (9,1,'Locked blocks','L5: under §501.045 a seller "is entitled to no compensation" for services performed before cancellation. Confirm that the start date and deposit spending must wait until the cancellation deadline passes, and whether the FTC 10 business days or Florida''s 10 days governs the refund.');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (10,1,'Locked blocks','L6: what should the "document containing the requirements of this chapter" be (full text of Chapter 515, or a summary), and which department publication is current? Is the draft delivery acknowledgment acceptable given that the statute requires delivery only?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (11,1,'Locked blocks','L7: may the written agreement to longer permit and start periods under §489.126(2)(a) sit inside the main contract, or should it be a separate signed writing? When no permit is required, from what date does the 90-day start period run?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (12,1,'Clause options','C03: tax wording. Is "No sales tax is added to this Contract" accurate for all five trades under lump-sum pricing, and what should a retail-sale-plus-installation contract say?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (13,1,'Clause options','C04: does §687.03''s 18 percent cap apply to contract interest on late construction payments, and how does §715.12''s statutory interest (the §55.03 rate plus 12 percent per annum) interact with a contract rate? The research mentions a delinquency charge of up to 5 percent allowed only if the contract provides for it; which statute is that, and does it apply to these contracts?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (14,1,'Clause options','C04: is a grace period with interest from the original due date (not from the end of the grace period) acceptable?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (15,1,'Clause options','C05-C: is a text or email authorization for urgent work, followed by a signed Change Order within 2 business days, workable under the Recovery Fund rules on change orders (rule 61G4-21.003 refers to contracts showing the original scope and change orders)?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (16,1,'Clause options','C06: should any option include a delay remedy for the Owner (for example liquidated damages), or is "no money penalty" acceptable as written?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (17,1,'Clause options','C08-D: does the business need EPA RRP firm certification before this clause is offered, and should the builder block the clause (or the job) when certification is not on file?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (18,1,'Clause options','C09-B: can a contractor record the Notice of Commencement as the owner''s authorized agent under §713.13 when the owner has signed it, and what does the agent authorization need to say? Please also confirm the 2026 single-family permit exemption under $7,500 reported in the research (not verified here) and its effect on C09-C.');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (19,1,'Clause options','C11: are the exclusions (hairline cracks, water chemistry, settling) enforceable against a consumer, and should the library disclaim implied warranties? This draft does not disclaim them.');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (20,1,'Clause options','C12: can the §713.06 Contractor''s Final Payment Affidavit be signed as a §92.525 written declaration instead of before a notary (spec decision C14)? Is the "Owner is not required to make the final payment until the affidavit is delivered" sentence an accurate statement?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (21,1,'Clause options','C12-C: is the retainage option consistent with §715.12(7) as drafted, including using 15 days as the default punch-list period?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (22,1,'Clause options','C13: is the asymmetric structure (C13-A) enforceable against a consumer? Is the C13-B convenience fee enforceable, and how should it be expressed to be treated as a reasonable estimate rather than a penalty? Does the certified-mail termination letter described in §489.126(3)(b)3.a also satisfy the contract notice clause?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (23,1,'Clause options','C14: please write or approve each package: arbitration rules and fee split for Package B; whether a jury waiver and prevailing-party fee clause (Package C) is enforceable in a consumer home improvement contract; whether a one-sided fee clause would become reciprocal under Florida law; small claims carve-out; and whether the lien-enforcement carve-out is correctly stated.');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (24,1,'Clause options','C14 and L3: should any package, or any option, allow the parties to opt out of Chapter 558? This draft never does.');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (25,1,'Clause options','C15: are liability caps (C15-A contract price, C15-C amount paid for the affected part) enforceable in a Florida consumer construction contract, and are the carve-outs sufficient? What wording should be used for workers'' compensation exemptions?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (26,1,'Clause options','C16-B: does a 72-hour offer expiry interact with the three-day cancellation right in any way that must be explained to the homeowner?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (27,1,'Clause options','C18: is the checkbox opt-in with written withdrawal enough for marketing use of photos of a private home?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (28,1,'Clause options','C19: are the ESIGN consumer-consent disclosures on the pre-signing consent screen sufficient for the required notices (L1 separate signature, L5 forms, L6 delivery) to be delivered electronically?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (29,1,'Clause options','General: the draft disclaimer wording ("This contract template has not been reviewed by an attorney. Have your attorney review it.") and the post-review line ("Template reviewed by [attorney], Florida Bar #, on [date]"). Are both acceptable, and what must accompany a custom clause approved by a client''s own attorney?');
INSERT OR IGNORE INTO contract_attorney_questions (n, version, group_name, text) VALUES (30,1,'Clause options','General: does any option here, or the builder''s rule of inserting blocks by contract amount, trade and sale location, raise unauthorized-practice concerns for the software provider?');
INSERT OR IGNORE INTO contract_exclusion_checklists (version, trade, items_json) VALUES (1,'All trades','["Permit fees above the amount in the Estimate", "engineering or survey unless listed", "repair of conditions found under C08", "HOA application fees", "work by other trades not listed", "relocation or storage of furniture and belongings", "landscape, irrigation or sod restoration beyond the work area", "electrical or plumbing work beyond the connection points listed"]');
INSERT OR IGNORE INTO contract_exclusion_checklists (version, trade, items_json) VALUES (1,'Pools and spas','["Rock removal, dewatering and hauling beyond the Estimate''s allowance", "screen enclosure", "fence or barrier unless it is the chosen safety feature", "electrical service upgrade or panel work", "gas line", "start-up chemicals beyond first fill", "water for the first fill", "landscaping and sod", "drainage beyond the pool deck", "repair of driveway or sidewalk damage from equipment access"]');
INSERT OR IGNORE INTO contract_exclusion_checklists (version, trade, items_json) VALUES (1,'Tile and flooring','["Subfloor or slab repair and leveling beyond the Estimate", "moisture mitigation", "removal of more than one existing layer", "asbestos testing or abatement", "moving appliances", "baseboard or trim replacement", "door trimming", "furniture moving"]');
INSERT OR IGNORE INTO contract_exclusion_checklists (version, trade, items_json) VALUES (1,'Remodeling','["Structural changes", "asbestos or mold remediation", "lead-based paint abatement (as opposed to lead-safe work practices)", "relocation of plumbing or electrical beyond the Estimate", "appliance installation", "cabinet or countertop templating changes after approval", "painting outside the work area"]');
INSERT OR IGNORE INTO contract_exclusion_checklists (version, trade, items_json) VALUES (1,'Hardscape and outdoor living','["Rock removal", "soil import or export beyond the Estimate", "drainage systems", "irrigation relocation", "electrical or gas for outdoor kitchens", "engineering for decks or pergolas", "HOA architectural approval fees", "tree or root removal"]');
INSERT OR IGNORE INTO contract_exclusion_checklists (version, trade, items_json) VALUES (1,'General services (painting, handyman)','["Surface repair beyond light patching", "wood rot replacement", "pressure washing unless listed", "lead-safe work beyond what the Estimate lists", "moving furniture", "hauling of owner''s items"]');
INSERT OR IGNORE INTO contract_admin_settings (key, value, set_by) VALUES ('review_released_to_rafa', '0', 'migration');
